using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry;

// SOURCE_ONLY_UNCOMPILED mirror. Source contexts are literal source scopes,
// not claimed elaborated telescopes. No emit, Reg or admission has run.
internal sealed class FiniteProtectedDualWordDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Geometry/FiniteProtectedDualWord.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Protected dual words on raw finite families.", H("FiniteProtectedDualWord"),
        Blocks(
            Paragraph(Text("The raw authority is OriginalLabelTwoSum.Family = LowerSet (Finset V). Empty raw membership, original ambient ghosts and the Fintype native instances are preserved. The full word is partitioned into disjoint pairs and possibly empty criticals with earlier-face dependencies. Protection is upward within K and whole-symbol, contains all criticals, and only emitted uppers must be proper. Current carries a true ordered decomposition. Existing native CollapsePair and Sequence witnesses are constructed with exact deletion and terminal equality. All source remains uncompiled; Reg and every native and delivery obligation remain open.")),
            Node("decl-1", "Symbol", "Symbol", "Raw pair and critical symbols, including empty critical faces.", "variable {V : Type*} [Fintype V] [DecidableEq V]\ninductive Symbol (V : Type*) where\n  | pair (L : Finset V) (v : V)\n  | critical (S : Finset V)\n  deriving DecidableEq", DescribeRole.Definition),
            Node("decl-2", "Symbol.faces", "Symbol.faces", "The exact raw faces owned by each symbol.", "variable {V : Type*} [Fintype V] [DecidableEq V]\ndef faces : Symbol V → Finset (Finset V)", DescribeRole.Definition),
            Node("decl-3", "Symbol.isCritical", "Symbol.isCritical", "Critical-symbol predicate used by the empty-protection consumer.", "variable {V : Type*} [Fintype V] [DecidableEq V]\ndef isCritical : Symbol V → Prop", DescribeRole.Definition),
            Node("decl-4", "Symbol.pair_faces", "Symbol.pair_faces", "Exact two-face expansion of a pair symbol.", "variable {V : Type*} [Fintype V] [DecidableEq V]\n@[simp] theorem pair_faces (L : Finset V) (v : V) :\n    (Symbol.pair L v).faces = {L, insert v L}", DescribeRole.Theorem),
            Node("decl-5", "Symbol.critical_faces", "Symbol.critical_faces", "Exact singleton expansion of a critical symbol.", "variable {V : Type*} [Fintype V] [DecidableEq V]\n@[simp] theorem critical_faces (S : Finset V) :\n    (Symbol.critical S).faces = {S}", DescribeRole.Theorem),
            Node("decl-6", "emittedOne", "emittedOne", "Only unprotected pairs emit their two faces.", "variable {V : Type*} [Fintype V] [DecidableEq V]\ndef emittedOne (H : Finset (Finset V)) : Symbol V → Finset (Finset V)", DescribeRole.Definition),
            Node("decl-7", "emittedFaces", "emittedFaces", "Finite union of exactly the emissions in the given list.", "variable {V : Type*} [Fintype V] [DecidableEq V]\ndef emittedFaces (H : Finset (Finset V)) : List (Symbol V) → Finset (Finset V)", DescribeRole.Definition),
            Node("decl-8", "rawDual", "rawDual", "Existing finite dualTable on the raw LowerSet membership table, with proved downward closure.", "variable {V : Type*} [Fintype V] [DecidableEq V]\ndef rawDual (W : Finset V) (K : Family V) : Family V", DescribeRole.Definition),
            Node("decl-9", "RawFaces", "RawFaces", "Nonempty current faces are supported in W and have an outside-K or not-yet-emitted complement.", "variable {V : Type*} [Fintype V] [DecidableEq V]\ndef RawFaces (W : Finset V) (K : Family V)\n    (R : Finset (Finset V)) (s : Finset V) : Prop", DescribeRole.Definition),
            Node("decl-10", "rawEndpoint", "rawEndpoint", "Raw exact endpoint, with upward protection only inside K.", "variable {V : Type*} [Fintype V] [DecidableEq V]\ndef rawEndpoint (W : Finset V) (K : Family V) (H : Finset (Finset V))\n    (hUp : ∀ {T U}, T ∈ H → U ∈ K → T ⊆ U → U ∈ H) : Family V", DescribeRole.Definition),
            Node("decl-11", "protectedEndpoint", "protectedEndpoint", "Native projection after constructing the raw endpoint.", "variable {V : Type*} [Fintype V] [DecidableEq V]\ndef protectedEndpoint (W : Finset V) (K : Family V) (H : Finset (Finset V))\n    (hUp : ∀ {T U}, T ∈ H → U ∈ K → T ⊆ U → U ∈ H) :\n    PreAbstractSimplicialComplex V", DescribeRole.Definition),
            Node("decl-12", "Word", "Word", "Full raw partition and ordered dependencies, with no desired native output premise.", "variable {V : Type*} [Fintype V] [DecidableEq V]\nstructure Word (W : Finset V) (K : Family V) where\n  word : List (Symbol V)\n  supported : OriginalLabelTwoSum.Supported W K\n  pair_data : ∀ L v, Symbol.pair L v ∈ word →\n    L ∈ K ∧ insert v L ∈ K ∧ v ∉ L\n  critical_data : ∀ S, Symbol.critical S ∈ word → S ∈ K\n  partition : word.Pairwise (fun σ τ => Disjoint σ.faces τ.faces)\n  covers : ∀ s, s ∈ K ↔ ∃ i : Fin word.length, s ∈ (word.get i).faces\n  pair_dependency : ∀ (prefix suffix : List (Symbol V)) L v,\n    word = prefix ++ Symbol.pair L v :: suffix →\n    ∀ T, T ⊂ insert v L → T ≠ L → ∃ σ ∈ prefix, T ∈ σ.faces\n  critical_dependency : ∀ (prefix suffix : List (Symbol V)) S,\n    word = prefix ++ Symbol.critical S :: suffix →\n    ∀ T, T ⊂ S → ∃ σ ∈ prefix, T ∈ σ.faces", DescribeRole.Structure),
            Node("decl-13", "Contract", "Contract", "Upward, whole-symbol and all-critical protection; only emitted uppers must be proper.", "variable {V : Type*} [Fintype V] [DecidableEq V]\nstructure Contract (W : Finset V) (K : Family V) extends Word W K where\n  protected : Finset (Finset V)\n  protected_subset : ∀ T ∈ protected, T ∈ K\n  protected_upward : ∀ {T U}, T ∈ protected → U ∈ K → T ⊆ U → U ∈ protected\n  protected_pair : ∀ L v, Symbol.pair L v ∈ word →\n    (L ∈ protected ↔ insert v L ∈ protected)\n  critical_protected : ∀ S, Symbol.critical S ∈ word → S ∈ protected\n  emitted_proper : ∀ L v, Symbol.pair L v ∈ word → L ∉ protected → insert v L ⊂ W", DescribeRole.Structure),
            Node("decl-14", "Contract.current", "Contract.current", "Downward closure derived at an actual word=prefix++suffix decomposition.", "variable {V : Type*} [Fintype V] [DecidableEq V]\nvariable {W : Finset V} {K : Family V} (d : Contract W K)\ndef current (prefix suffix : List (Symbol V))\n    (hword : d.word = prefix ++ suffix) : PreAbstractSimplicialComplex V", DescribeRole.Definition),
            Node("decl-15", "Contract.nativePair", "Contract.nativePair", "Existing native CollapsePair with lower W\\U, upper W\\L and all actual cofaces proved.", "variable {V : Type*} [Fintype V] [DecidableEq V]\nvariable {W : Finset V} {K : Family V} (d : Contract W K)\ndef nativePair (prefix suffix : List (Symbol V)) (L : Finset V) (v : V)\n    (hword : d.word = prefix ++ Symbol.pair L v :: suffix) (hL : L ∉ d.protected) :\n    CollapsePair V", DescribeRole.Definition),
            Node("decl-16", "Contract.protectedEndpoint_mem", "Contract.protectedEndpoint_mem", "Exact union of the nonempty finite raw dual and nonempty protected complements.", "variable {V : Type*} [Fintype V] [DecidableEq V]\nvariable {W : Finset V} {K : Family V} (d : Contract W K)\ntheorem protectedEndpoint_mem (s : Finset V) :\n    s ∈ protectedEndpoint W K d.protected d.protected_upward ↔\n      s ∈ project (rawDual W K) ∨\n        (s.Nonempty ∧ ∃ T ∈ d.protected, s = W \\ T)", DescribeRole.Theorem),
            Node("decl-17", "Contract.protectedDualWordSequence", "Contract.protectedDualWordSequence", "Constructive universal P02 witness using only existing Sequence.refl, Sequence.step and equality transport.", "variable {V : Type*} [Fintype V] [DecidableEq V]\nvariable {W : Finset V} {K : Family V} (d : Contract W K)\ndef protectedDualWordSequence :\n    Sequence (simplex W) (protectedEndpoint W K d.protected d.protected_upward)", DescribeRole.Definition),
            Node("decl-18", "criticalFaces", "criticalFaces", "Finite collection of the word criticals, retaining the empty face.", "variable {V : Type*} [Fintype V] [DecidableEq V]\ndef criticalFaces : List (Symbol V) → Finset (Finset V)", DescribeRole.Definition),
            Node("decl-19", "Word.noCritical_unprotected", "Word.noCritical_unprotected", "No-critical data constructs empty protection and an actual native Sequence to the raw dual projection.", "variable {V : Type*} [Fintype V] [DecidableEq V]\nvariable {W : Finset V} {K : Family V} (d : Word W K)\ndef noCritical_unprotected\n    (hcrit : ∀ σ ∈ d.word, ¬ σ.isCritical)\n    (hproper : ∀ L v, Symbol.pair L v ∈ d.word → insert v L ⊂ W) :\n    Sequence (simplex W) (project (rawDual W K))", DescribeRole.Definition),
            Node("decl-20", "Word.maximalCritical_protected", "Word.maximalCritical_protected", "Maximality derives upward protection; disjoint partition derives whole symbols; the universal engine constructs the native Sequence.", "variable {V : Type*} [Fintype V] [DecidableEq V]\nvariable {W : Finset V} {K : Family V} (d : Word W K)\ndef maximalCritical_protected\n    (hmax : ∀ S, Symbol.critical S ∈ d.word → ∀ T ∈ K, S ⊆ T → T = S)\n    (hproper : ∀ L v, Symbol.pair L v ∈ d.word → insert v L ⊂ W) :\n    Sequence (simplex W)\n      (protectedEndpoint W K (criticalFaces d.word) (by\n        intro S T hS hT hST\n        have hc := (mem_criticalFaces d.word S).mp hS\n        rw [hmax S hc T hT hST]\n        exact hS))", DescribeRole.Definition))));

    private static DocumentBlock Node(string id, string declaration, string title,
        string prose, string rawContract, DescribeRole role) => Describe.Lean(
            DescribeId.Create(id), DeclarationHandle.Create(Prefix + declaration), H(title),
            StatementSource.FromLean(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text(prose)), Paragraph(Text(rawContract))), role);
}
